	public void recreateNPCInfoList() {
		clientThread.invokeLater(() -> {
			if (client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null
					&& client.getLocalPlayer().getPlayerComposition() != null)
			{
				nameAndIdContainer.getNpcList().clear();

				recreateNPCInfoListForWorldView(client.getTopLevelWorldView());

				nameAndIdContainer.setCurrentTask(slayerPluginService.getTask() == null ? "" : slayerPluginService.getTask());
			}
		});
	}

	private void recreateNPCInfoListForWorldView(WorldView wv) {
		for (NPC npc : wv.npcs())
		{
			NPCInfo npcInfo = createNpcInfo(npc);
			if (npcInfo != null)
			{
				nameAndIdContainer.getNpcList().add(npcInfo);

				if (!wv.isInstance())
				{
					respawnManager.memorizeNpc(npc);
				}
			}
			else
			{
				respawnManager.forgetNpc(npc.getIndex());
			}
		}

		for (WorldView subWv : wv.worldViews())
		{
			recreateNPCInfoListForWorldView(subWv);
		}
	}

	/**
	 * Builds an NPCInfo for the given NPC, or null when it should not be highlighted.
	 */
	public NPCInfo createNpcInfo(NPC npc) {
		Color globalTileColor = config.useGlobalTileColor() ? config.globalTileColor() : null;
		Color globalFillColor = config.useGlobalTileColor() ? config.globalFillColor() : null;

		HighlightColor tile = resolveHighlightColor(nameAndIdContainer.getTileNames(), nameAndIdContainer.getTileIds(), npc,
				coalesceColor(globalTileColor, config.tileColor()), coalesceColor(globalFillColor, config.tileFillColor()));
		HighlightColor trueTile = resolveHighlightColor(nameAndIdContainer.getTrueTileNames(), nameAndIdContainer.getTrueTileIds(), npc,
				coalesceColor(globalTileColor, config.trueTileColor()), coalesceColor(globalFillColor, config.trueTileFillColor()));
		HighlightColor swTile = resolveHighlightColor(nameAndIdContainer.getSwTileNames(), nameAndIdContainer.getSwTileIds(), npc,
				coalesceColor(globalTileColor, config.swTileColor()), coalesceColor(globalFillColor, config.swTileFillColor()));
		HighlightColor swTrueTile = resolveHighlightColor(nameAndIdContainer.getSwTrueTileNames(), nameAndIdContainer.getSwTrueTileIds(), npc,
				coalesceColor(globalTileColor, config.swTrueTileColor()), coalesceColor(globalFillColor, config.swTrueTileFillColor()));
		HighlightColor hull = resolveHighlightColor(nameAndIdContainer.getHullNames(), nameAndIdContainer.getHullIds(), npc, config.hullColor(),
				config.hullFillColor());
		HighlightColor area = resolveHighlightColor(nameAndIdContainer.getAreaNames(), nameAndIdContainer.getAreaIds(), npc, config.areaColor(),
				null);
		HighlightColor outline = resolveHighlightColor(nameAndIdContainer.getOutlineNames(), nameAndIdContainer.getOutlineIds(), npc,
				config.outlineColor(), null);
		HighlightColor clickbox = resolveHighlightColor(nameAndIdContainer.getClickboxNames(), nameAndIdContainer.getClickboxIds(), npc,
				config.clickboxColor(), config.clickboxFillColor());

		boolean isTask = slayerPluginIntegration.checkSlayerPluginEnabled() && slayerPluginService != null
				&& slayerPluginService.getTargets().contains(npc);
		boolean ignoreDead = isInSpecificNameList(nameAndIdContainer.getIgnoreDeadExclusionList(), npc)
				|| isInSpecificIdList(nameAndIdContainer.getIgnoreDeadExclusionIDList(), npc);

		if (!tile.isHighlight() && !trueTile.isHighlight() && !swTile.isHighlight() && !swTrueTile.isHighlight()
				&& !hull.isHighlight() && !area.isHighlight() && !outline.isHighlight() && !clickbox.isHighlight() && !isTask)
		{
			return null;
		}

		return new NPCInfo(npc, tile, trueTile, swTile, swTrueTile, hull, area, outline, clickbox, isTask, ignoreDead);
	}

	private Color coalesceColor(Color color, Color defaultColor) {
		return color != null ? color : defaultColor;
	}

	public String configListToString(boolean add, String name, List<String> strList, int preset) {
		if (add)
		{
			boolean foundName = false;
			String newName = preset > 0 ? name + ":" + preset : name;
			for (String str : strList)
			{
				if (str.startsWith(name + ":") || str.equalsIgnoreCase(name))
				{
					strList.set(strList.indexOf(str), newName);
					foundName = true;
				}
			}

			if (!foundName)
			{
				strList.add(newName);
			}
		}
		else
		{
			strList.removeIf(str -> str.toLowerCase().startsWith(name + ":") || str.equalsIgnoreCase(name));
		}
		return configReaderService.listToCsv(strList);
	}

	public void updateListConfig(boolean add, String name, int preset) {
		if (!add)
		{
			removeAllTagStyles(name);
			return;
		}

		if (config.tagStyleModeSet().contains(tagStyleMode.TILE))
		{
			config.setTileNames(configListToString(add, name, nameAndIdContainer.getTileNames(), preset));
		}
		if (config.tagStyleModeSet().contains(tagStyleMode.TRUE_TILE))
		{
			config.setTrueTileNames(configListToString(add, name, nameAndIdContainer.getTrueTileNames(), preset));
		}
		if (config.tagStyleModeSet().contains(tagStyleMode.SW_TILE))
		{
			config.setSwTileNames(configListToString(add, name, nameAndIdContainer.getSwTileNames(), preset));
		}
		if (config.tagStyleModeSet().contains(tagStyleMode.SW_TRUE_TILE))
		{
			config.setSwTrueTileNames(configListToString(add, name, nameAndIdContainer.getSwTrueTileNames(), preset));
		}
		if (config.tagStyleModeSet().contains(tagStyleMode.HULL))
		{
			config.setHullNames(configListToString(add, name, nameAndIdContainer.getHullNames(), preset));
		}
		if (config.tagStyleModeSet().contains(tagStyleMode.AREA))
		{
			config.setAreaNames(configListToString(add, name, nameAndIdContainer.getAreaNames(), preset));
		}
		if (config.tagStyleModeSet().contains(tagStyleMode.OUTLINE))
		{
			config.setOutlineNames(configListToString(add, name, nameAndIdContainer.getOutlineNames(), preset));
		}
		if (config.tagStyleModeSet().contains(tagStyleMode.CLICKBOX))
		{
			config.setClickboxNames(configListToString(add, name, nameAndIdContainer.getClickboxNames(), preset));
		}
	}

	public HighlightColor resolveHighlightColor(List<String> strList, List<String> idList, NPC npc, Color configColor,
			Color configFillColor) {
		for (String entry : idList)
		{
			int id = -1;
			String preset = "";
			if (entry.contains(":"))
			{
				String[] strArr = entry.split(":");
				if (configReaderService.isNumeric(strArr[0]))
				{
					id = Integer.parseInt(strArr[0]);
				}
				preset = strArr[1];
			}
			else if (configReaderService.isNumeric(entry))
			{
				id = Integer.parseInt(entry);
			}

			if (id == npc.getId())
			{
				return new HighlightColor(true, colorManager.getHighlightColor(preset, configColor),
						colorManager.getHighlightFillColor(preset, configFillColor));
			}
		}

		if (npc.getName() != null)
		{
			String name = npc.getName().toLowerCase();
			for (String entry : strList)
			{
				String nameStr = entry;
				String preset = "";
				if (entry.contains(":"))
				{
					String[] strArr = entry.split(":");
					nameStr = strArr[0];
					preset = strArr[1];
				}

				if (WildcardMatcher.matches(nameStr, name))
				{
					return new HighlightColor(true, colorManager.getHighlightColor(preset, configColor),
							colorManager.getHighlightFillColor(preset, configFillColor));
				}
			}
		}
		return new HighlightColor(false, configColor, configFillColor);
	}

	public boolean isInSpecificNameList(List<String> strList, NPC npc) {
		if (npc.getName() != null)
		{
			String name = npc.getName().toLowerCase();
			for (String entry : strList)
			{
				String nameStr = entry;
				if (entry.contains(":"))
				{
					String[] strArr = entry.split(":");
					nameStr = strArr[0];
				}

				if (WildcardMatcher.matches(nameStr, name))
				{
					return true;
				}
			}
		}
		return false;
	}

	public boolean isInSpecificIdList(List<String> strList, NPC npc) {
		int id = npc.getId();
		for (String entry : strList)
		{
			String idStr = entry;
			if (entry.contains(":"))
			{
				String[] strArr = entry.split(":");
				idStr = strArr[0];
			}

			if (configReaderService.isNumeric(idStr) && Integer.parseInt(idStr) == id)
			{
				return true;
			}
		}
		return false;
	}

	public boolean isInAnyNameList(NPC npc) {
		return isInSpecificNameList(nameAndIdContainer.getTileNames(), npc) || isInSpecificNameList(nameAndIdContainer.getTrueTileNames(), npc)
				|| isInSpecificNameList(nameAndIdContainer.getSwTileNames(), npc)
				|| isInSpecificNameList(nameAndIdContainer.getSwTrueTileNames(), npc)
				|| isInSpecificNameList(nameAndIdContainer.getHullNames(), npc)
				|| isInSpecificNameList(nameAndIdContainer.getAreaNames(), npc)
				|| isInSpecificNameList(nameAndIdContainer.getOutlineNames(), npc)
				|| isInSpecificNameList(nameAndIdContainer.getClickboxNames(), npc);
	}

	public boolean isInAnyIdList(NPC npc) {
		return isInSpecificIdList(nameAndIdContainer.getTileIds(), npc) || isInSpecificIdList(nameAndIdContainer.getTrueTileIds(), npc)
				|| isInSpecificIdList(nameAndIdContainer.getSwTileIds(), npc) || isInSpecificIdList(nameAndIdContainer.getSwTrueTileIds(), npc)
				|| isInSpecificIdList(nameAndIdContainer.getHullIds(), npc) || isInSpecificIdList(nameAndIdContainer.getAreaIds(), npc)
				|| isInSpecificIdList(nameAndIdContainer.getOutlineIds(), npc) || isInSpecificIdList(nameAndIdContainer.getClickboxIds(), npc);
	}

	public boolean isInAnyList(NPC npc) {
		return isInAnyNameList(npc) || isInAnyIdList(npc);
	}

	private void removeAllTagStyles(String name) {
		config.setTileNames(configListToString(false, name, nameAndIdContainer.getTileNames(), 0));
		config.setTrueTileNames(configListToString(false, name, nameAndIdContainer.getTrueTileNames(), 0));
		config.setSwTileNames(configListToString(false, name, nameAndIdContainer.getSwTileNames(), 0));
		config.setSwTrueTileNames(configListToString(false, name, nameAndIdContainer.getSwTrueTileNames(), 0));
		config.setHullNames(configListToString(false, name, nameAndIdContainer.getHullNames(), 0));
		config.setAreaNames(configListToString(false, name, nameAndIdContainer.getAreaNames(), 0));
		config.setOutlineNames(configListToString(false, name, nameAndIdContainer.getOutlineNames(), 0));
		config.setClickboxNames(configListToString(false, name, nameAndIdContainer.getClickboxNames(), 0));
	}
}

package com.betternpchighlight.managers;

import static net.runelite.api.MenuAction.MENU_ACTION_DEPRIORITIZE_OFFSET;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import javax.inject.Inject;

import com.betternpchighlight.BetterNpcHighlightConfig;
import com.betternpchighlight.BetterNpcHighlightConfig.tagStyleMode;
import com.betternpchighlight.BetterNpcHighlightConfig.presetColorAmount;
import com.betternpchighlight.data.NPCInfo;
import com.betternpchighlight.data.NameAndIdContainer;
import com.google.common.collect.ImmutableSet;

import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.game.NpcUtil;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

public class MenuManager {
	private static final String TAG_OPTION = "Tag-NPC";
	private static final String UNTAG_OPTION = "Untag-NPC";
	private static final String RESET_COLOR_OPTION = "Reset color";
	private static final String PRESET_COLOR_OPTION_PREFIX = "Preset color ";

	private static final Set<MenuAction> NPC_MENU_ACTIONS = ImmutableSet
			.of(MenuAction.NPC_FIRST_OPTION, MenuAction.NPC_SECOND_OPTION, MenuAction.NPC_THIRD_OPTION, MenuAction.NPC_FOURTH_OPTION,
					MenuAction.NPC_FIFTH_OPTION, MenuAction.WIDGET_TARGET_ON_NPC, MenuAction.ITEM_USE_ON_NPC);

	/**
	 * Splits a menu target into its color tags, NPC name and optional
	 * "(level-N)" suffix so the name and level can be recolored independently.
	 */
	private static final Pattern MENU_TARGET_PATTERN = Pattern
			.compile("^(?<leadingTags>(?:<[^>]+>)*)" + "(?<name>[^<(]+?)" + "(?<trailingTags>(?:<[^>]+>)*)"
					+ "(?:\\s*(?<level>\\(level-\\d+\\)))?$");

	@Inject
	private Client client;
	@Inject
	private BetterNpcHighlightConfig config;
	@Inject
	private NameAndIdContainer nameAndIdContainer;
	@Inject
	private NpcUtil npcUtil;
	@Inject
	private ColorManager colorManager;
	@Inject
	private ConfigTransformManager configTransformManager;

	/**
	 * Entry point, invoked for every menu entry that is added. Dispatches to the
	 * handler for the entry's action type.
	 */
	public void onMenuEntryAdded(MenuEntryAdded event) {
		// TODO: https://github.com/riktenx/better-npc-highlight/pull/12
		// Once NPC submenu entries are supported, modify this so those can be recolored
		NPC npc = event.getMenuEntry().getNpc();
		if (npc == null)
		{
			return;
		}

		MenuAction action = MenuAction.of(normalizeType(event.getType()));
		if (NPC_MENU_ACTIONS.contains(action))
		{
			colorizeNpcMenuEntry(event, npc);
		}
		else if (action == MenuAction.EXAMINE_NPC)
		{
			handleExamineMenuEntry(event, npc);
		}
	}

	// ----------------------------------------------------------------//
	// NPC interaction entries (e.g. "Attack", "Use item ->", ...)
	// ----------------------------------------------------------------//

	/**
	 * Recolors the NPC name on regular interaction menu entries.
	 */
	private void colorizeNpcMenuEntry(MenuEntryAdded event, NPC npc) {
		Color color = resolveNpcActionColor(npc);
		if (color != null)
		{
			setLastMenuEntryTarget(getMenuEntryString(event.getTarget(), color, config.highlightMenuNamesLevel()));
		}
	}

	/**
	 * Resolves the color for a regular NPC interaction entry, or null to leave it
	 * untouched.
	 */
	private Color resolveNpcActionColor(NPC npc) {
		if (npcUtil.isDying(npc))
		{
			return config.deadNpcMenuColor();
		}

		if (config.highlightMenuNames() && npc.getName() != null && configTransformManager.isInAnyList(npc))
		{
			return getNpcDisplayColor(npc);
		}

		return null;
	}

	// ----------------------------------------------------------------//
	// Examine entry (Tag-NPC / Untag-NPC and preset colors)
	// ----------------------------------------------------------------//

	private void handleExamineMenuEntry(MenuEntryAdded event, NPC npc) {
		if (npc.getName() == null || !isTaggingEnabled())
		{
			return;
		}

		String option = configTransformManager.isInAnyList(npc) ? UNTAG_OPTION : TAG_OPTION;

		// Recolor the existing "Examine" entry when it shows an untag action.
		if (option.equals(UNTAG_OPTION) && shouldColorize(npc))
		{
			setLastMenuEntryTarget(colorizeTarget(npc, event.getTarget()));
		}

		// Holding shift adds a dedicated tag/untag entry with a preset submenu.
		if (client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			addTagMenuEntry(event, npc, option);
		}
	}

	/**
	 * Whether the Tag/Untag menu options should be shown, based on the configured
	 * tag styles.
	 */
	private boolean isTaggingEnabled() {
		Set<tagStyleMode> styles = config.tagStyleModeSet();
		if (styles.contains(tagStyleMode.NONE))
		{
			return styles.size() > 1;
		}
		return !styles.isEmpty();
	}

	/**
	 * Adds the shift-held "Tag-NPC"/"Untag-NPC" entry and its preset submenu.
	 */
	private void addTagMenuEntry(MenuEntryAdded event, NPC npc, String option) {
		MenuEntry parent = client
				.createMenuEntry(-1)
				.setOption(option)
				.setTarget(colorizeTarget(npc, event.getTarget()))
				.setIdentifier(event.getIdentifier())
				.setWorldViewId(event.getMenuEntry().getWorldViewId())
				.setParam0(event.getActionParam0())
				.setParam1(event.getActionParam1())
				.setType(MenuAction.RUNELITE)
				.onClick(this::handleTagOptionClicked);

		if (parent != null)
		{
			addPresetColorSubmenu(npc, parent);
		}
	}

	/**
	 * Builds the preset color submenu under the tag/untag entry.
	 */
	private void addPresetColorSubmenu(NPC npc, MenuEntry parent) {
		if (config.presetColorAmount() == presetColorAmount.ZERO)
		{
			return;
		}

		List<Color> colors = loadPresetColors();
		Menu submenu = parent.createSubMenu();

		if (!colors.isEmpty())
		{
			int preset = 1;
			for (Color color : colors)
			{
				if (color != null)
				{
					final int presetNumber = preset;
					submenu
							.createMenuEntry(0)
							.setOption(ColorUtil.prependColorTag(PRESET_COLOR_OPTION_PREFIX + preset, color))
							.setType(MenuAction.RUNELITE)
							.onClick(e -> tagNpcWithPreset(npc, presetNumber));
					preset++;
				}
			}
		}

		// Only offer "Reset color" for NPCs that are already tagged.
		if (nameAndIdContainer.getNpcInfoByNpc(npc) != null)
		{
			submenu
					.createMenuEntry(0)
					.setOption(RESET_COLOR_OPTION)
					.setType(MenuAction.RUNELITE)
					.onClick(e -> tagNpcWithPreset(npc, 0));
		}
	}

	/**
	 * Handles clicks on the shift-held "Tag-NPC"/"Untag-NPC" entry.
	 */
	private void handleTagOptionClicked(MenuEntry entry) {
		if (entry.getType() != MenuAction.RUNELITE)
		{
			return;
		}

		if (entry.getOption().equals(TAG_OPTION) || entry.getOption().equals(UNTAG_OPTION))
		{
			NPC npc = client.getWorldView(entry.getWorldViewId()).npcs().byIndex(entry.getIdentifier());
			if (npc.getName() != null)
			{
				configTransformManager.updateListConfig(entry.getOption().equals(TAG_OPTION), npc.getName().toLowerCase(), 0);
			}
		}
	}

	/**
	 * Tags an NPC with the given preset color (0 resets to the default).
	 */
	private void tagNpcWithPreset(NPC npc, int preset) {
		if (npc.getName() != null)
		{
			configTransformManager.updateListConfig(true, npc.getName().toLowerCase(), preset);
		}
	}

	// ----------------------------------------------------------------//
	// Color resolution
	// ----------------------------------------------------------------//

	/**
	 * Color used for tag/untag related entries, falling back to the tag color when
	 * the NPC has no specific highlight.
	 */
	private Color getNpcDisplayColor(NPC npc) {
		Color color = getSpecificNpcColor(npc);
		return color != null ? color : colorManager.getTagColor();
	}

	/**
	 * Color of the NPC's current highlight, or null when it is not highlighted.
	 */
	private Color getSpecificNpcColor(NPC npc) {
		NPCInfo npcInfo = nameAndIdContainer.getNpcInfoByNpc(npc);
		return npcInfo != null ? colorManager.getSpecificColor(npcInfo) : null;
	}

	/**
	 * Whether an examine/tag target should be recolored.
	 */
	private boolean shouldColorize(NPC npc) {
		return config.highlightMenuNames() || (npc.isDead() && config.deadNpcMenuColor() != null);
	}

	/**
	 * Recolors a target string for examine/tag entries, leaving it unchanged when
	 * colorization is disabled.
	 */
	private String colorizeTarget(NPC npc, String target) {
		if (!shouldColorize(npc))
		{
			return target;
		}

		Color color = (npc.isDead() && config.deadNpcMenuColor() != null) ? config.deadNpcMenuColor() : getNpcDisplayColor(npc);
		return getMenuEntryString(target, color, config.highlightMenuNamesLevel());
	}

	// ----------------------------------------------------------------//
	// Preset colors
	// ----------------------------------------------------------------//

	/**
	 * Loads the enabled preset colors in order.
	 */
	private List<Color> loadPresetColors() {
		List<Color> colors = new ArrayList<>();
		presetColorAmount amount = config.presetColorAmount();

		if (amount == presetColorAmount.ONE)
		{
			colors.add(config.presetColor1());
		}
		else if (amount == presetColorAmount.TWO)
		{
			colors.add(config.presetColor1());
			colors.add(config.presetColor2());
		}
		else if (amount == presetColorAmount.THREE)
		{
			colors.add(config.presetColor1());
			colors.add(config.presetColor2());
			colors.add(config.presetColor3());
		}
		else if (amount == presetColorAmount.FOUR)
		{
			colors.add(config.presetColor1());
			colors.add(config.presetColor2());
			colors.add(config.presetColor3());
			colors.add(config.presetColor4());
		}
		else if (amount == presetColorAmount.FIVE)
		{
			colors.add(config.presetColor1());
			colors.add(config.presetColor2());
			colors.add(config.presetColor3());
			colors.add(config.presetColor4());
			colors.add(config.presetColor5());
		}

		return colors;
	}

	// ----------------------------------------------------------------//
	// Menu target string building
	// ----------------------------------------------------------------//

	/**
	 * Rebuilds a menu target string, coloring the name and (optionally) its level.
	 */
	private String getMenuEntryString(String target, Color color, boolean includeLevel) {
		Matcher matcher = MENU_TARGET_PATTERN.matcher(target);
		if (!matcher.matches())
		{
			return ColorUtil.prependColorTag(Text.removeTags(target), color);
		}

		String name = matcher.group("name");
		String trailingTags = matcher.group("trailingTags");
		String levelPart = matcher.group("level");

		StringBuilder rebuilt = new StringBuilder(ColorUtil.prependColorTag(name, color));
		if (includeLevel)
		{
			if (levelPart != null)
			{
				rebuilt.append("  ").append(ColorUtil.prependColorTag(levelPart, color));
			}
		}
		else
		{
			if (trailingTags != null && !trailingTags.isEmpty())
			{
				rebuilt.append(trailingTags);
			}
			if (levelPart != null)
			{
				rebuilt.append("  ").append(levelPart);
			}
		}

		return rebuilt.toString();
	}

	/**
	 * Overwrites the target of the most recently added menu entry.
	 */
	private void setLastMenuEntryTarget(String target) {
		MenuEntry[] entries = client.getMenuEntries();
		entries[entries.length - 1].setTarget(target);
		client.setMenuEntries(entries);
	}

	private int normalizeType(int type) {
		return type >= MENU_ACTION_DEPRIORITIZE_OFFSET ? type - MENU_ACTION_DEPRIORITIZE_OFFSET : type;
	}
}

package com.betternpchighlight.managers;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import javax.inject.Inject;
import javax.inject.Singleton;

import com.betternpchighlight.data.MemorizedNpc;

import lombok.AllArgsConstructor;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GraphicsObject;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GraphicsObjectCreated;
import net.runelite.api.gameval.SpotanimID;

/**
 * Tracks highlighted NPCs across their death/respawn cycles and exposes the
 * NPCs that currently have an active respawn timer to draw.
 *
 * <p>The logic mirrors the RuneLite NPC Indicators plugin: an NPC is memorized
 * when it spawns, its death is confirmed on the following game tick (by
 * checking it despawned while still in view range), and its respawn time and
 * spawn tile are learned from the next time it spawns.</p>
 */
@Singleton
public class RespawnManager {
	private static final int MAX_ACTOR_VIEW_RANGE = 15;
	private static final int MAX_RESPAWN_TIME_TICKS = 500;

	@Inject
	private Client client;

	/**
	 * NPCs currently being tracked, keyed by NPC index.
	 */
	@Getter
	private final Map<Integer, MemorizedNpc> memorizedNpcs = new HashMap<>();

	/**
	 * Dead NPCs that currently have an active respawn timer to display.
	 */
	@Getter
	private final Map<Integer, MemorizedNpc> deadNpcsToDisplay = new HashMap<>();

	/**
	 * The time the last game tick was processed, used to smooth the seconds
	 * countdown between ticks.
	 */
	@Getter
	private Instant lastTickUpdate = Instant.now();

	private final List<NPC> spawnedNpcsThisTick = new ArrayList<>();
	private final List<DespawnedNpc> despawnedNpcsThisTick = new ArrayList<>();
	private final Set<WorldPoint> teleportGraphicsObjectSpawnedThisTick = new HashSet<>();
	private WorldPoint lastPlayerLocation;
	private boolean skipNextSpawnCheck = false;

	@AllArgsConstructor
	private static class DespawnedNpc {
		private final WorldPoint coord;
		private final int index;
	}

	/**
	 * Fully resets all state. Called on plugin startup and shutdown.
	 */
	public void reset() {
		memorizedNpcs.clear();
		deadNpcsToDisplay.clear();
		spawnedNpcsThisTick.clear();
		despawnedNpcsThisTick.clear();
		teleportGraphicsObjectSpawnedThisTick.clear();
		lastPlayerLocation = null;
		skipNextSpawnCheck = false;
	}

	/**
	 * Called when the game state changes to the login screen or a world hop.
	 */
	public void onGameStateChanged() {
		deadNpcsToDisplay.clear();
		memorizedNpcs.values().forEach(npc -> npc.setDiedOnTick(-1));
		lastPlayerLocation = null;
		skipNextSpawnCheck = true;
	}

	/**
	 * Registers an NPC for respawn tracking without treating it as a fresh
	 * spawn (used when rebuilding the list of highlighted NPCs).
	 */
	public void memorizeNpc(NPC npc) {
		memorizedNpcs.putIfAbsent(npc.getIndex(), new MemorizedNpc(npc));
	}

	/**
	 * Removes an NPC from respawn tracking because it is no longer highlighted.
	 */
	public void forgetNpc(int index) {
		memorizedNpcs.remove(index);
		deadNpcsToDisplay.remove(index);
	}

	/**
	 * Called when a highlighted NPC spawns.
	 */
	public void onNpcSpawned(NPC npc) {
		memorizeNpc(npc);
		spawnedNpcsThisTick.add(npc);
	}

	/**
	 * Called when an NPC despawns.
	 */
	public void onNpcDespawned(NPC npc) {
		if (memorizedNpcs.containsKey(npc.getIndex()))
		{
			despawnedNpcsThisTick.add(new DespawnedNpc(npc.getWorldLocation(), npc.getIndex()));
		}
	}

	/**
	 * Called when a graphics object is created, to detect NPCs that teleported.
	 */
	public void onGraphicsObjectCreated(GraphicsObjectCreated event) {
		GraphicsObject go = event.getGraphicsObject();
		if (go.getId() == SpotanimID.SMOKEPUFF)
		{
			teleportGraphicsObjectSpawnedThisTick.add(WorldPoint.fromLocal(client, go.getLocation()));
		}
	}

	/**
	 * Called on every game tick to validate spawns/despawns and update timers.
	 */
	public void onGameTick() {
		removeOldHighlightedRespawns();
		validateSpawnedNpcs();
		lastTickUpdate = Instant.now();

		Player local = client.getLocalPlayer();
		if (local != null)
		{
			lastPlayerLocation = local.getWorldLocation();
		}
	}

	private void removeOldHighlightedRespawns() {
		deadNpcsToDisplay.values().removeIf(x -> x.getDiedOnTick() + x.getRespawnTime() <= client.getTickCount() + 1);
	}

	private void validateSpawnedNpcs() {
		if (skipNextSpawnCheck)
		{
			skipNextSpawnCheck = false;
		}
		else
		{
			for (DespawnedNpc npc : despawnedNpcsThisTick)
			{
				if (!teleportGraphicsObjectSpawnedThisTick.isEmpty() && teleportGraphicsObjectSpawnedThisTick.contains(npc.coord))
				{
					// NPC teleported away, so this is not a death.
					continue;
				}

				if (isInViewRange(client.getLocalPlayer().getWorldLocation(), npc.coord))
				{
					MemorizedNpc mn = memorizedNpcs.get(npc.index);

					if (mn != null)
					{
						// This runs before the tick counter updates, so add 1.
						mn.setDiedOnTick(client.getTickCount() + 1);

						if (!mn.getPossibleRespawnLocations().isEmpty())
						{
							deadNpcsToDisplay.put(mn.getNpcIndex(), mn);
						}
					}
				}
			}

			for (NPC npc : spawnedNpcsThisTick)
			{
				if (!teleportGraphicsObjectSpawnedThisTick.isEmpty()
						&& (teleportGraphicsObjectSpawnedThisTick.contains(npc.getWorldLocation())
								|| teleportGraphicsObjectSpawnedThisTick.contains(getWorldLocationBehind(npc))))
				{
					// NPC teleported here, so this is not a respawn.
					continue;
				}

				if (lastPlayerLocation != null && isInViewRange(lastPlayerLocation, npc.getWorldLocation()))
				{
					MemorizedNpc mn = memorizedNpcs.get(npc.getIndex());

					if (mn.getDiedOnTick() != -1)
					{
						final int respawnTime = client.getTickCount() + 1 - mn.getDiedOnTick();

						// Prefer the shorter observed respawn time, and ignore
						// observations that are clearly incorrect.
						if ((mn.getRespawnTime() == -1 || respawnTime < mn.getRespawnTime()) && respawnTime <= MAX_RESPAWN_TIME_TICKS)
						{
							mn.setRespawnTime(respawnTime);
						}

						mn.setDiedOnTick(-1);
					}

					final WorldPoint npcLocation = npc.getWorldLocation();
					// An NPC can move on the same tick it spawns, so also
					// consider the tile behind it as a possible spawn location.
					final WorldPoint possibleOtherNpcLocation = getWorldLocationBehind(npc);

					mn.getPossibleRespawnLocations().removeIf(x -> !x.equals(npcLocation) && !x.equals(possibleOtherNpcLocation));

					if (mn.getPossibleRespawnLocations().isEmpty())
					{
						mn.getPossibleRespawnLocations().add(npcLocation);
						mn.getPossibleRespawnLocations().add(possibleOtherNpcLocation);
					}
				}
			}
		}

		spawnedNpcsThisTick.clear();
		despawnedNpcsThisTick.clear();
		teleportGraphicsObjectSpawnedThisTick.clear();
	}

	private static boolean isInViewRange(WorldPoint wp1, WorldPoint wp2) {
		return wp1.distanceTo(wp2) < MAX_ACTOR_VIEW_RANGE;
	}

	private static WorldPoint getWorldLocationBehind(NPC npc) {
		final int orientation = npc.getOrientation() / 256;
		int dx = 0;
		int dy = 0;

		switch (orientation)
		{
			case 0: // South
				dy = -1;
				break;
			case 1: // Southwest
				dx = -1;
				dy = -1;
				break;
			case 2: // West
				dx = -1;
				break;
			case 3: // Northwest
				dx = -1;
				dy = 1;
				break;
			case 4: // North
				dy = 1;
				break;
			case 5: // Northeast
				dx = 1;
				dy = 1;
				break;
			case 6: // East
				dx = 1;
				break;
			case 7: // Southeast
				dx = 1;
				dy = -1;
				break;
		}

		final WorldPoint currWP = npc.getWorldLocation();
		return new WorldPoint(currWP.getX() - dx, currWP.getY() - dy, currWP.getPlane());
	}
}

package com.betternpchighlight.managers;

import java.util.Optional;

import javax.inject.Inject;

import com.betternpchighlight.BetterNpcHighlightConfig;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginInstantiationException;
import net.runelite.client.plugins.PluginManager;

@Slf4j
public class SlayerPluginManager {
	@Inject
	private PluginManager pluginManager;

	@Inject
	private BetterNpcHighlightConfig config;

	public boolean checkSlayerPluginEnabled() {
		final Optional<Plugin> slayerPlugin = pluginManager.getPlugins().stream().filter(p -> p.getName().equals("Slayer")).findFirst();
		return slayerPlugin.isPresent() && pluginManager.isPluginEnabled(slayerPlugin.get());
	}

	public void enableSlayerPlugin() {
		try
		{
			final Optional<Plugin> slayerPlugin = pluginManager.getPlugins().stream().filter(p -> p.getName().equals("Slayer")).findFirst();
			if (slayerPlugin.isPresent() && !pluginManager.isPluginEnabled(slayerPlugin.get()) && config.slayerHighlight())
			{
				pluginManager.setPluginEnabled(slayerPlugin.get(), true);
				pluginManager.startPlugin(slayerPlugin.get());
			}
		}
		catch (PluginInstantiationException ex)
		{
			log.error("error starting slayer plugin", ex);
		}
	}
}

